INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('zendesk', 1, 'saas-product', 'saas', 'Zendesk', '問い合わせ対応・チケット管理の定番SaaS。API/Webhookでの外部連携が豊富', '{"strengths":["外部連携APIが豊富","マルチチャネル対応","導入実績が豊富"],"pricing":{"monthlyBaseFee":0,"monthlyPricePerUser":7000}}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('power_automate_zapier', 1, 'saas-product', 'saas', 'Power Automate / Zapier', 'SaaS間のデータ連携・自動化に特化したノーコードツール', '{"strengths":["ノーコードで連携を構築できる","対応SaaSコネクタが多い","低コストで開始できる"],"pricing":{"monthlyBaseFee":10000,"monthlyPricePerUser":0}}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 8);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('looker_studio', 1, 'saas-product', 'saas', 'Looker Studio', '複数データソースを無料で可視化できるダッシュボードSaaS', '{"strengths":["無料で始められる","多様なデータソースに接続できる","共有が容易"],"pricing":{"monthlyBaseFee":0,"monthlyPricePerUser":0}}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 9);
